using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using SkiaSharp;
internal static class CharacterPortraits {
 internal static void Validate(Data data){if(data.portraits==null)data.portraits=new Dictionary<string,string>();if(data.portraits.Count>30||data.portraits.Any(x=>String.IsNullOrEmpty(x.Key)||x.Key.Length>100||!Regex.IsMatch(x.Value??"", "^[a-f0-9]{64}$")))throw new InvalidDataException("Portraits invalides.");}
 internal static byte[] Prepare(string file){DofusImageRuntime.EnsureNative();var info=new FileInfo(file);if(!info.Exists||info.Length>10*1024*1024)throw new InvalidDataException("Choisissez une image de moins de 10 Mo.");string extension=info.Extension.ToLowerInvariant();if(!new[]{".png",".jpg",".jpeg",".webp"}.Contains(extension))throw new InvalidDataException("Formats acceptés : PNG, JPG et WebP.");using(var codec=SKCodec.Create(file)){if(codec==null)throw new InvalidDataException("Cette image n’a pas pu être décodée.");var size=codec.Info;if(size.Width<1||size.Height<1||size.Width>16384||size.Height>16384||(long)size.Width*size.Height>40000000)throw new InvalidDataException("L’image est trop grande. Maximum : 40 millions de pixels.");using(var bitmap=SKBitmap.Decode(codec)){if(bitmap==null)throw new InvalidDataException("Image invalide.");using(var surface=SKSurface.Create(new SKImageInfo(384,384,SKColorType.Bgra8888,SKAlphaType.Premul))){surface.Canvas.Clear(SKColors.Transparent);float scale=Math.Min(384f/bitmap.Width,384f/bitmap.Height);float width=bitmap.Width*scale,height=bitmap.Height*scale;using(var image=SKImage.FromBitmap(bitmap))surface.Canvas.DrawImage(image,new SKRect((384-width)/2,(384-height)/2,(384+width)/2,(384+height)/2),new SKSamplingOptions(SKFilterMode.Linear));using(var image=surface.Snapshot())using(var bytes=image.Encode(SKEncodedImageFormat.Png,100))return bytes.ToArray();}}}}
 internal static string Save(Store store,byte[] bytes){string hash=WorkspaceNext.Hash(bytes);string directory=Path.Combine(store.Root,"Portraits");Directory.CreateDirectory(directory);string file=Path.Combine(directory,hash+".png");if(!File.Exists(file)){string temp=file+".tmp";try{File.WriteAllBytes(temp,bytes);File.Move(temp,file);}finally{if(File.Exists(temp))File.Delete(temp);}}return hash;}
 internal static BitmapSource Decode(byte[] bytes){using(var input=new MemoryStream(bytes)){var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.StreamSource=input;bitmap.EndInit();bitmap.Freeze();return bitmap;}}
 internal static BitmapSource Load(Store store,string hash){if(!Regex.IsMatch(hash??"","^[a-f0-9]{64}$"))return null;string file=Path.Combine(store.Root,"Portraits",hash+".png");try{if(!File.Exists(file)||new FileInfo(file).Length>1024*1024)return null;var bytes=File.ReadAllBytes(file);return WorkspaceNext.Hash(bytes)==hash?Decode(bytes):null;}catch{return null;}}
 internal static Border View(Store store,DofusCharacter character,int size=48,Brush line=null,Brush raised=null,Brush accent=null){string hash;if(character==null||!store.Value.portraits.TryGetValue(character.id,out hash))hash="";return View(Load(store,hash),character==null?"?":character.name,size,line,raised,accent);}
 internal static Border View(BitmapSource image,string name,int size=72,Brush line=null,Brush raised=null,Brush accent=null){var frame=new Border{Width=size,Height=size,CornerRadius=new CornerRadius(size/2.0),BorderThickness=new Thickness(1),BorderBrush=line??Brushes.DimGray,Background=raised??Brushes.Transparent,Margin=new Thickness(0,0,12,0)};if(image==null)frame.Child=new TextBlock{Text=String.IsNullOrWhiteSpace(name)?"?":name.Trim().Substring(0,1).ToUpperInvariant(),FontFamily=new FontFamily("Palatino Linotype"),FontSize=size*.43,Foreground=accent??Brushes.Goldenrod,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};else frame.Background=new ImageBrush(image){Stretch=Stretch.Uniform};return frame;}
 internal static Border FullView(Store store,DofusCharacter character,int width=80,int height=108,Brush line=null,Brush raised=null,Brush accent=null){string hash;var image=character!=null&&store.Value.portraits.TryGetValue(character.id,out hash)?Load(store,hash):null;if(image==null){var fallback=View(store,character,Math.Min(width,64),line,raised,accent);fallback.VerticalAlignment=VerticalAlignment.Center;return fallback;}return new Border{Width=width,Height=height,Child=new Image{Source=image,Stretch=Stretch.Uniform,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center},ToolTip=character.name};}
 internal static void Test(string folder){DofusImageRuntime.EnsureNative();Directory.CreateDirectory(folder);string input=Path.Combine(folder,"sample.webp");using(var surface=SKSurface.Create(new SKImageInfo(48,80))){surface.Canvas.Clear(new SKColor(98,180,130,190));using(var image=surface.Snapshot())using(var data=image.Encode(SKEncodedImageFormat.Webp,90))File.WriteAllBytes(input,data.ToArray());}var png=Prepare(input);var decoded=Decode(png);if(decoded.PixelWidth!=384||decoded.PixelHeight!=384)throw new Exception("Conversion WebP");var store=new Store(Path.Combine(folder,"data"));var character=new DofusCharacter{id="portrait-test",name="Portrait test"};store.Value.dofus.characters.Add(character);store.Value.dofus.active=character.id;string hash=Save(store,png);PersonalWorkflows.Change(store,()=>store.Value.portraits[character.id]=hash);var reopened=new Store(store.Root);if(reopened.Value.portraits[character.id]!=hash||Load(reopened,hash)==null)throw new Exception("Portrait non conservé");if(Load(reopened,"../escape")!=null)throw new Exception("Chemin portrait");var other=new DofusCharacter{id="other",name="Autre"};if(reopened.Value.portraits.ContainsKey(other.id))throw new Exception("Portrait partagé");string invalid=Path.Combine(folder,"bad.webp");File.WriteAllText(invalid,"not an image");bool rejected=false;try{Prepare(invalid);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Image corrompue acceptée");}
}
